class Solution {
    public int findMaxConsecutiveOnes(int[] nums)
    {
        int count = 0;
        int counter = 0;
        for(int i = 0; i < nums.length; i++)
        {
            
            if(nums[i] == 1)
            {
                counter++;
                
            }
            if( count <= counter)
            {
                count = counter;
                
            }
            if(nums[i] != 1)
            {
                counter = 0;
            }


            // if(nums[i] == 1)
            // {
            //     counter++;
            // }

            // if(count <= counter)
            // {
            //     count = counter;
            // }

            // if(nums[i] != 1)
            // {
            //     counter = 0;
            // }

            
            



            
        }
        return count;
    }
}


